//! `POST /models/veo-3.1-fast-generate-preview:predictLongRunning` — **Veo 3.1 Fast** (`veo-3.1-fast-generate-preview`).
//! Starts an ASYNC video generation (text-to-video, or image-to-video via
//! `image`) and returns the operation name; poll it with
//! [`crate::api::requests::videos::poll_video_operation`], then download with
//! [`crate::api::requests::files::download_video`]. Audio is generated by
//! default — put dialogue/SFX cues in the prompt.
//!
//! Docs: <https://ai.google.dev/gemini-api/docs/veo>

use serde::Serialize;

use crate::api::requests::videos::common::{build_veo_body, run_predict_long_running, VeoBodyParts};
use crate::api::types::video_types::veo_person_generation::VeoPersonGeneration;
use crate::api::types::video_types::veo_aspect_ratio::VeoAspectRatio;
use crate::api::types::video_types::veo_duration::VeoDuration;
use crate::api::types::video_types::veo_image_input::VeoImageInput;
use crate::api::types::video_types::veo_resolution::VeoResolution;
use crate::creds::google_gemini_api_key::GoogleGeminiApiKey;
use crate::error::google_gemini_error::GoogleGeminiError;

pub use crate::api::requests::videos::common::VeoOperationName;

/// The exact model identifier this binding pins.
pub const VEO_3_1_FAST_MODEL_ID: &str = "veo-3.1-fast-generate-preview";

/// Top-level argument to [`generate_veo_3_1_fast`]. Borrows the API key separately
/// from the request body so callers can log/persist (and PRICE) the request
/// without touching the credential.
#[derive(Clone, Debug)]
pub struct GenerateVeo31FastArgs<'a> {
  pub api_key: &'a GoogleGeminiApiKey,
  pub request: Veo31FastRequest,
}

/// The material part of a Veo 3.1 Fast request — drives both the wire body and the
/// [`client_core::CostCalculator`] price (see `cost.rs`).
#[derive(Clone, Debug, Serialize)]
pub struct Veo31FastRequest {
  /// Text prompt (max ~1,024 tokens). Dialogue in quotes and SFX descriptions
  /// drive the generated audio.
  pub prompt: String,

  /// What NOT to generate.
  #[serde(skip_serializing_if = "Option::is_none")]
  pub negative_prompt: Option<String>,

  /// Conditioning image for image-to-video. `None` = pure text-to-video.
  #[serde(skip_serializing_if = "Option::is_none")]
  pub image: Option<VeoImageInput>,

  /// Final interpolation frame (requires `image`). Not yet live-validated.
  #[serde(skip_serializing_if = "Option::is_none")]
  pub last_frame: Option<VeoImageInput>,

  /// Style/asset reference images (≤ 3; requires an 8-second duration).
  /// Not yet live-validated.
  #[serde(skip_serializing_if = "Vec::is_empty", default)]
  pub reference_images: Vec<VeoImageInput>,

  /// A previous Veo result URI to EXTEND. Not yet live-validated.
  #[serde(skip_serializing_if = "Option::is_none")]
  pub video_uri: Option<String>,

  /// People policy — Google constrains the allowed value by task (see the
  /// enum docs).
  #[serde(skip_serializing_if = "Option::is_none")]
  pub person_generation: Option<VeoPersonGeneration>,

  /// 16:9 (default) or 9:16.
  #[serde(skip_serializing_if = "Option::is_none")]
  pub aspect_ratio: Option<VeoAspectRatio>,

  /// Output resolution — drives the price. Server default 720p when `None`.
  /// 1080p/4K requires an 8-second duration.
  #[serde(skip_serializing_if = "Option::is_none")]
  pub resolution: Option<VeoResolution>,

  /// Clip length. Server default 8 s when `None`.
  #[serde(skip_serializing_if = "Option::is_none")]
  pub duration: Option<VeoDuration>,
}

/// Start a Veo 3.1 Fast generation. Returns the operation name to poll.
pub async fn generate_veo_3_1_fast(args: GenerateVeo31FastArgs<'_>) -> Result<VeoOperationName, GoogleGeminiError> {
  let GenerateVeo31FastArgs { api_key, request } = args;
  let body = build_veo_body(VeoBodyParts {
    prompt: &request.prompt,
    image: request.image.as_ref(),
    last_frame: request.last_frame.as_ref(),
    reference_images: &request.reference_images,
    video_uri: request.video_uri.as_deref(),
    aspect_ratio: request.aspect_ratio.map(|a| a.as_str()),
    resolution: request.resolution.map(|r| r.as_str()),
    duration_seconds: request.duration.map(|d| d.seconds()),
    negative_prompt: request.negative_prompt.as_deref(),
    person_generation: request.person_generation.map(|p| p.as_str()),
  });
  run_predict_long_running(api_key, VEO_3_1_FAST_MODEL_ID, &body).await
}

#[cfg(test)]
mod tests {
  use serde_json::json;

  use super::*;
  use crate::api::requests::videos::common::build_veo_body;

  /// Input → exact outbound HTTP body.
  #[test]
  fn text_to_video_wire_shape() {
    let request = Veo31FastRequest {
      prompt: "a hummingbird in slow motion".to_string(),
      negative_prompt: Some("blurry".to_string()),
      image: None,
      last_frame: None,
      reference_images: vec![],
      video_uri: None,
      person_generation: None,
      aspect_ratio: Some(VeoAspectRatio::Landscape16x9),
      resolution: Some(VeoResolution::P1080),
      duration: Some(VeoDuration::S8),
    };
    let body = build_veo_body(VeoBodyParts {
      prompt: &request.prompt,
      image: request.image.as_ref(),
      last_frame: None,
      reference_images: &[],
      video_uri: None,
      aspect_ratio: request.aspect_ratio.map(|a| a.as_str()),
      resolution: request.resolution.map(|r| r.as_str()),
      duration_seconds: request.duration.map(|d| d.seconds()),
      negative_prompt: request.negative_prompt.as_deref(),
      person_generation: None,
    });
    assert_eq!(
      serde_json::to_value(&body).unwrap(),
      json!({
        "instances": [{ "prompt": "a hummingbird in slow motion" }],
        "parameters": {
          "aspectRatio": "16:9",
          "resolution": "1080p",
          "durationSeconds": 8,
          "negativePrompt": "blurry"
        }
      })
    );
  }

  /// Image-to-video conditioning rides as `fileUri` (Files API) — never data: URLs.
  #[test]
  fn image_to_video_wire_shape_uses_file_uri() {
    let body = build_veo_body(VeoBodyParts {
      prompt: "animate this",
      image: Some(&VeoImageInput::FileUri {
        uri: "https://generativelanguage.googleapis.com/v1beta/files/xyz".to_string(),
        mime: "image/png".to_string(),
      }),
      last_frame: None,
      reference_images: &[],
      video_uri: None,
      aspect_ratio: None,
      resolution: None,
      duration_seconds: None,
      negative_prompt: None,
      person_generation: Some("allow_adult"),
    });
    assert_eq!(
      serde_json::to_value(&body).unwrap(),
      json!({
        "instances": [{
          "prompt": "animate this",
          "image": { "fileUri": "https://generativelanguage.googleapis.com/v1beta/files/xyz",
                     "mimeType": "image/png" }
        }],
        "parameters": { "personGeneration": "allow_adult" }
      })
    );
  }

  /// Live start→poll→download — costs real money (~$0.40 (4s @ 720p)). Reads
  /// `external/credentials/gemini_api_key.txt`.
  #[tokio::test]
  #[ignore] // live — costs money
  async fn live_generate_veo_3_1_fast() -> anyhow::Result<()> {
    use crate::api::requests::files::download_video::download_video::{download_video, DownloadVideoArgs};
    use crate::api::requests::videos::poll_video_operation::poll_video_operation::{
      poll_video_operation, PollVideoOperationArgs, VeoPollOutcome,
    };

    crate::test_utils::setup_test_logging::setup_test_logging();
    let api_key = crate::test_utils::get_test_api_key::get_test_api_key()?;
    let request = Veo31FastRequest {
      prompt: "A paper boat drifting down a rain gutter, cinematic close-up".to_string(),
      negative_prompt: None,
      image: None,
      last_frame: None,
      reference_images: vec![],
      video_uri: None,
      person_generation: None,
      aspect_ratio: None,
      resolution: Some(VeoResolution::P720),
      duration: Some(VeoDuration::S4),
    };
    let operation = generate_veo_3_1_fast(GenerateVeo31FastArgs { api_key: &api_key, request }).await?;

    // Poll (10s cadence, ≤6 min) until done, then download the bytes.
    for _ in 0..36 {
      tokio::time::sleep(std::time::Duration::from_secs(10)).await;
      match poll_video_operation(PollVideoOperationArgs { api_key: &api_key, operation: &operation }).await? {
        VeoPollOutcome::Pending => continue,
        VeoPollOutcome::Failed { code, message } => anyhow::bail!("veo failed: {code:?} {message}"),
        VeoPollOutcome::Succeeded(videos) => {
          assert!(!videos.is_empty());
          let bytes = download_video(DownloadVideoArgs { api_key: &api_key, uri: &videos[0].uri }).await?;
          assert!(bytes.len() > 10_000, "suspiciously small video");
          return Ok(());
        }
      }
    }
    anyhow::bail!("operation did not complete within 6 minutes")
  }
}
